// ===== SPARKLE EFFECT =====
function initSparkles() {
  var canvas = document.getElementById('sparkle-canvas');
  var ctx = canvas.getContext('2d');
  var sparkles = [];

  function resize() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  }
  resize();
  window.addEventListener('resize', resize);

  document.addEventListener('mousemove', function(e) {
    if (Math.random() > 0.85) {
      sparkles.push({
        x: e.clientX,
        y: e.clientY,
        size: Math.random() * 3 + 1,
        life: 1,
        vx: (Math.random() - 0.5) * 2,
        vy: (Math.random() - 0.5) * 2,
        color: Math.random() > 0.5 ? '#ff69b4' : '#9333ea'
      });
    }
  });

  function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (var i = sparkles.length - 1; i >= 0; i--) {
      var s = sparkles[i];
      s.life -= 0.02;
      s.x += s.vx;
      s.y += s.vy;
      s.size *= 0.98;
      if (s.life <= 0) { sparkles.splice(i, 1); continue; }
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2);
      ctx.fillStyle = s.color;
      ctx.globalAlpha = s.life;
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    requestAnimationFrame(animate);
  }
  animate();
}

// ===== SCROLL TO TOP =====
function initScrollToTop() {
  var btn = document.getElementById('scroll-top-btn');
  window.addEventListener('scroll', function() {
    if (window.scrollY > 300) {
      btn.classList.add('visible');
    } else {
      btn.classList.remove('visible');
    }
  });
  btn.addEventListener('click', function() {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
}

// ===== LIGHTBOX =====
function initLightbox() {
  var overlay = document.getElementById('lightbox-overlay');
  var closeBtn = document.getElementById('lightbox-close');
  var prevBtn = document.getElementById('lightbox-prev');
  var nextBtn = document.getElementById('lightbox-next');

  closeBtn.addEventListener('click', closeLightbox);
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) closeLightbox();
  });
  prevBtn.addEventListener('click', function() {
    currentLightboxIndex = (currentLightboxIndex - 1 + galleryPhotos.length) % galleryPhotos.length;
    updateLightbox();
  });
  nextBtn.addEventListener('click', function() {
    currentLightboxIndex = (currentLightboxIndex + 1) % galleryPhotos.length;
    updateLightbox();
  });

  document.addEventListener('keydown', function(e) {
    if (!overlay.classList.contains('active')) return;
    if (e.key === 'Escape') closeLightbox();
    if (e.key === 'ArrowLeft') { currentLightboxIndex = (currentLightboxIndex - 1 + galleryPhotos.length) % galleryPhotos.length; updateLightbox(); }
    if (e.key === 'ArrowRight') { currentLightboxIndex = (currentLightboxIndex + 1) % galleryPhotos.length; updateLightbox(); }
  });
}

function openLightbox(index) {
  currentLightboxIndex = index;
  var overlay = document.getElementById('lightbox-overlay');
  overlay.classList.add('active');
  document.body.style.overflow = 'hidden';
  updateLightbox();
}
window.openLightbox = openLightbox;

function updateLightbox() {
  var img = document.getElementById('lightbox-img');
  var caption = document.getElementById('lightbox-caption');
  img.src = galleryPhotos[currentLightboxIndex].src;
  caption.textContent = galleryPhotos[currentLightboxIndex].caption;
}

function closeLightbox() {
  var overlay = document.getElementById('lightbox-overlay');
  overlay.classList.remove('active');
  document.body.style.overflow = '';
}

// ===== LOVE COUNTER =====
function getLoveCounterHTML() {
  var start = new Date("February 23, 2025 00:00:00");
  var now = new Date();
  var diff = now.getTime() - start.getTime();
  var days = Math.floor(diff / (1000 * 60 * 60 * 24));
  var hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
  var minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
  var seconds = Math.floor((diff % (1000 * 60)) / 1000);

  return '<div class="love-counter"><div class="love-counter-content"><h3> Together For</h3><div class="love-counter-grid"><div class="love-counter-item"><span class="count-value" id="lc-days">' + days + '</span><span class="count-label">Days</span></div><div class="love-counter-item"><span class="count-value" id="lc-hours">' + hours + '</span><span class="count-label">Hours</span></div><div class="love-counter-item"><span class="count-value" id="lc-minutes">' + minutes + '</span><span class="count-label">Minutes</span></div><div class="love-counter-item"><span class="count-value" id="lc-seconds">' + seconds + '</span><span class="count-label">Seconds</span></div></div></div></div>';
}

function startLoveCounter() {
  if (loveCounterInterval) clearInterval(loveCounterInterval);
  loveCounterInterval = setInterval(function() {
    var start = new Date("February 23, 2025 00:00:00");
    var now = new Date();
    var diff = now.getTime() - start.getTime();
    var days = Math.floor(diff / (1000 * 60 * 60 * 24));
    var hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    var minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    var seconds = Math.floor((diff % (1000 * 60)) / 1000);
    var el = document.getElementById('lc-days');
    if (el) el.textContent = days;
    el = document.getElementById('lc-hours');
    if (el) el.textContent = hours;
    el = document.getElementById('lc-minutes');
    if (el) el.textContent = minutes;
    el = document.getElementById('lc-seconds');
    if (el) el.textContent = seconds;
  }, 1000);
}

