function initTimelinePage() {
  var MONTHSARY_DAY = 23;
  var ANNIVERSARY_START = new Date("February 23, 2025 00:00:00");

  function formatDate(date) {
    var months = ["January","February","March","April","May","June","July","August","September","October","November","December"];
    return months[date.getMonth()] + " " + date.getDate() + ", " + date.getFullYear();
  }

  function padZero(num) { return num < 10 ? "0" + num : num; }

  function getOrdinal(n) {
    var s = ["th","st","nd","rd"];
    var v = n % 100;
    return n + (s[(v - 20) % 10] || s[v] || s[0]);
  }

  function getMonthNumber(targetDate) {
    return (targetDate.getFullYear() - ANNIVERSARY_START.getFullYear()) * 12 + (targetDate.getMonth() - ANNIVERSARY_START.getMonth());
  }

  function isMonthsaryToday() { return new Date().getDate() === MONTHSARY_DAY; }

  function getCurrentMonthsaryNumber() {
    var now = new Date();
    return (now.getFullYear() - ANNIVERSARY_START.getFullYear()) * 12 + (now.getMonth() - ANNIVERSARY_START.getMonth());
  }

  function isAnniversaryToday() {
    var now = new Date();
    return now.getMonth() === ANNIVERSARY_START.getMonth() && now.getDate() === ANNIVERSARY_START.getDate() && now.getFullYear() > ANNIVERSARY_START.getFullYear();
  }

  function getNextMonthsary() {
    var now = new Date();
    var targetMonth = now.getDate() < MONTHSARY_DAY ? now.getMonth() : now.getMonth() + 1;
    var targetYear = now.getFullYear();
    if (targetMonth > 11) { targetMonth -= 12; targetYear++; }
    return new Date(targetYear, targetMonth, MONTHSARY_DAY, 0, 0, 0);
  }

  function showGreetingModal() {
    var modal = document.getElementById('monthsary-modal');
    var modalIcon = document.getElementById('modal-icon');
    var modalTitle = document.getElementById('modal-title');
    var monthLabel = document.getElementById('modal-month-label');
    var dateLabel = document.getElementById('modal-date-label');
    var modalMessage = document.getElementById('modal-message');
    var closeBtn = document.getElementById('modal-close-btn');
    var closeX = document.getElementById('modal-close-x');
    var backdrop = document.getElementById('modal-backdrop');

    if (isAnniversaryToday()) {
      var yearNum = new Date().getFullYear() - ANNIVERSARY_START.getFullYear();
      var ordinalYear = getOrdinal(yearNum);
      modalIcon.textContent = '\ud83d\udc8d';
      modalTitle.textContent = 'Happy ' + ordinalYear + ' Anniversary!';
      monthLabel.textContent = ordinalYear + ' Year Together \ud83c\udf89';
      modalMessage.innerHTML = '#JustInLoveWithRose\ud83e\udd0d \ud83d\udc96<br>' + ordinalYear + ' year of love, laughter, and forever! \ud83e\udd42<br>Mahal kita, today and always! \ud83c\udf39\u2728';
    } else {
      var monthNum = getCurrentMonthsaryNumber();
      var ordinalMonth = getOrdinal(monthNum);
      modalIcon.textContent = '';
      modalTitle.textContent = 'Happy ' + ordinalMonth + ' Monthsary!';
      monthLabel.textContent = ordinalMonth + ' Month Together \ud83d\udc8d';
      modalMessage.innerHTML = '#JustInLoveWithRose\ud83e\udd0d<br>Another beautiful month of loving you.<br>Here\'s to forever and always! \ud83c\udf39\u2728';
    }

    if (dateLabel) dateLabel.textContent = formatDate(new Date());
    modal.classList.add('active');
    document.body.style.overflow = 'hidden';

    function closeModal() {
      modal.classList.remove('active');
      modal.classList.add('closing');
      document.body.style.overflow = '';
      setTimeout(function() { modal.classList.remove('closing'); }, 500);
    }

    closeBtn.addEventListener('click', closeModal);
    closeX.addEventListener('click', closeModal);
    backdrop.addEventListener('click', closeModal);
  }

  function updateCountdown() {
    var now = new Date();
    var headerText = document.getElementById('countdown-header-text');

    if (isMonthsaryToday()) {
      var monthNum = getCurrentMonthsaryNumber();
      var ordinalMonth = getOrdinal(monthNum);
      document.getElementById("days").innerHTML = "\ud83c\udf89";
      document.getElementById("hours").innerHTML = "\ud83d\udc96";
      document.getElementById("minutes").innerHTML = "\ud83c\udf39";
      document.getElementById("seconds").innerHTML = "\u2728";
      if (headerText) {
        headerText.textContent = isAnniversaryToday() ? "\ud83c\udf89 Happy Anniversary! \ud83c\udf89" : "\ud83c\udf89 Happy " + ordinalMonth + " Monthsary! \ud83c\udf89";
      }
      var label = document.getElementById("monthsary-label");
      if (label) label.innerHTML = "Happy " + ordinalMonth + " Monthsary, #JustInLoveWithRose\ud83e\udd0d! \ud83d\udc96<br>Since February 23, 2025 \ud83d\udc96";
      return;
    }

    var nextMonthsary = getNextMonthsary();
    var distance = nextMonthsary.getTime() - now.getTime();
    var d = Math.floor(distance / (1000 * 60 * 60 * 24));
    var h = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    var m = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
    var s = Math.floor((distance % (1000 * 60)) / 1000);

    document.getElementById("days").innerHTML = padZero(d);
    document.getElementById("hours").innerHTML = padZero(h);
    document.getElementById("minutes").innerHTML = padZero(m);
    document.getElementById("seconds").innerHTML = padZero(s);

    if (headerText) headerText.textContent = "Next Monthsary Countdown ";
    var nextMonthNum = getMonthNumber(nextMonthsary);
    var ordinalNext = getOrdinal(nextMonthNum);
    var label2 = document.getElementById("monthsary-label");
    if (label2) label2.innerHTML = "Next: " + formatDate(nextMonthsary) + " (" + ordinalNext + " Month)<br>Since February 23, 2025 \ud83d\udc96";
  }

  updateCountdown();
  var countdownInterval = setInterval(updateCountdown, 1000);
  if (isMonthsaryToday()) setTimeout(showGreetingModal, 800);

  return function cleanup() { clearInterval(countdownInterval); };
}

