// ===== ROUTING =====
function navigateTo(page) {
  currentPage = page;
  window.location.hash = page;
  renderPage();
  var nav = document.getElementById('main-nav');
  if (nav) nav.classList.remove('active');
  window.scrollTo(0, 0);
}
window.navigateTo = navigateTo;

function renderPage() {
  var content = document.getElementById('page-content');
  var pageMap = {
    'home': getHomePage,
    'about': getAboutPage,
    'gallery': getGalleryPage,
    'timeline': getTimelinePage,
    'messages': getMessagesPage,
    'music': getMusicPage,
    'surprise': getSurprisePage
  };

  if (timelineCleanup) { timelineCleanup(); timelineCleanup = null; }
  if (loveCounterInterval) { clearInterval(loveCounterInterval); loveCounterInterval = null; }
  if (quoteInterval) { clearInterval(quoteInterval); quoteInterval = null; }

  var pageFn = pageMap[currentPage] || getHomePage;
  content.innerHTML = pageFn();

  var navLinks = document.querySelectorAll('nav a');
  navLinks.forEach(function(link) {
    link.classList.remove('active-nav');
    if (link.getAttribute('data-page') === currentPage) link.classList.add('active-nav');
  });

  if (currentPage === 'timeline') timelineCleanup = initTimelinePage();
  if (currentPage === 'music') syncMusicPageUI();
  if (currentPage === 'home') { startLoveCounter(); startQuoteRotation(); }
}

window.addEventListener('hashchange', function() {
  var hash = window.location.hash.replace('#', '') || 'home';
  currentPage = hash;
  renderPage();
});

// ===== MUSIC PLAYER LOGIC =====
function formatTime(sec) {
  if (isNaN(sec) || sec < 0) return '0:00';
  var m = Math.floor(sec / 60);
  var s = Math.floor(sec % 60);
  return m + ':' + (s < 10 ? '0' : '') + s;
}

function selectSong(index) {
  if (index < 0 || index >= songs.length) return;
  currentSongIndex = index;
  audio.src = songs[index].file;
  audio.load();
  audio.play().then(function() {
    isPlaying = true;
    updateAllUI();
  }).catch(function(e) {
    console.log('Playback requires user interaction:', e);
    isPlaying = true;
    updateAllUI();
  });
}
window.selectSong = selectSong;

function togglePlay() {
  if (currentSongIndex === -1) { selectSong(0); return; }
  if (isPlaying) { audio.pause(); isPlaying = false; }
  else { audio.play().catch(function() {}); isPlaying = true; }
  updateAllUI();
}
window.togglePlay = togglePlay;

function prevSong() { selectSong(currentSongIndex <= 0 ? songs.length - 1 : currentSongIndex - 1); }
function nextSong() { selectSong(currentSongIndex >= songs.length - 1 ? 0 : currentSongIndex + 1); }
window.prevSong = prevSong;
window.nextSong = nextSong;

function handleSongClick(e, index) {
  if (e.target.classList.contains('song-heart')) return;
  selectSong(index);
}
window.handleSongClick = handleSongClick;

function handleHeartClick(e, el) {
  e.stopPropagation();
  if (el.classList.contains('liked')) { el.classList.remove('liked'); el.textContent = '\u2661'; }
  else { el.classList.add('liked'); el.textContent = '\u2665'; }
}
window.handleHeartClick = handleHeartClick;

function seekFromPage(e) {
  var wrapper = document.getElementById('page-progress-wrapper');
  if (!wrapper || isNaN(audio.duration)) return;
  var rect = wrapper.getBoundingClientRect();
  audio.currentTime = ((e.clientX - rect.left) / rect.width) * audio.duration;
}
window.seekFromPage = seekFromPage;

function updateAllUI() {
  updateMiniPlayer();
  if (currentPage === 'music') syncMusicPageUI();
}

function updateMiniPlayer() {
  var miniPlayer = document.getElementById('mini-player');
  var miniTitle = document.getElementById('mini-title');
  var miniArtist = document.getElementById('mini-artist');
  var miniDisc = document.getElementById('mini-disc');
  var miniVis = document.getElementById('mini-visualizer');
  var miniPlayIcon = document.getElementById('mini-play-icon');

  if (currentSongIndex >= 0) {
    miniPlayer.classList.add('visible');
    miniTitle.textContent = songs[currentSongIndex].title;
    miniArtist.textContent = songs[currentSongIndex].artist;
    if (isPlaying) {
      miniDisc.classList.add('spinning');
      miniVis.classList.add('active');
      miniPlayIcon.innerHTML = '<rect x="7" y="5" width="3" height="14"/><rect x="14" y="5" width="3" height="14"/>';
    } else {
      miniDisc.classList.remove('spinning');
      miniVis.classList.remove('active');
      miniPlayIcon.innerHTML = '<polygon points="8,5 19,12 8,19"/>';
    }
  } else {
    miniPlayer.classList.remove('visible');
  }
}

function syncMusicPageUI() {
  var disc = document.getElementById('disc');
  var visualizer = document.getElementById('visualizer');
  var npTitle = document.getElementById('np-title');
  var npArtist = document.getElementById('np-artist');
  var npStatus = document.getElementById('np-status');
  var pulseDot = document.getElementById('pulse-dot');
  var pagePlayIcon = document.getElementById('page-play-icon');

  if (!disc) return;

  if (currentSongIndex >= 0) {
    npTitle.textContent = songs[currentSongIndex].title;
    npArtist.textContent = songs[currentSongIndex].artist + ' \ud83d\udc96';
    if (isPlaying) {
      disc.classList.add('spinning');
      visualizer.classList.add('active');
      npStatus.textContent = 'Now Playing';
      if (pulseDot) pulseDot.style.background = '#ff1493';
      if (pagePlayIcon) pagePlayIcon.innerHTML = '<rect x="7" y="5" width="3" height="14"/><rect x="14" y="5" width="3" height="14"/>';
    } else {
      disc.classList.remove('spinning');
      visualizer.classList.remove('active');
      npStatus.textContent = 'Paused';
      if (pulseDot) pulseDot.style.background = '#d4a8ff';
      if (pagePlayIcon) pagePlayIcon.innerHTML = '<polygon points="8,5 19,12 8,19"/>';
    }
  }

  var songItems = document.querySelectorAll('.song-item');
  songItems.forEach(function(item, idx) {
    item.classList.remove('active');
    var indicator = item.querySelector('.song-play-indicator');
    if (idx === currentSongIndex) {
      item.classList.add('active');
      if (indicator && isPlaying) indicator.innerHTML = '<div class="mini-bars"><div class="mini-bar"></div><div class="mini-bar"></div><div class="mini-bar"></div></div>';
      else if (indicator) indicator.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><polygon points="8,5 19,12 8,19"/></svg>';
    } else {
      if (indicator) indicator.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><polygon points="8,5 19,12 8,19"/></svg>';
    }
  });
}

// Audio time update
audio.addEventListener('timeupdate', function() {
  if (isNaN(audio.duration)) return;
  var percent = (audio.currentTime / audio.duration) * 100;
  var miniFill = document.getElementById('mini-progress-fill');
  var miniCurTime = document.getElementById('mini-current-time');
  var miniTotTime = document.getElementById('mini-total-time');
  if (miniFill) miniFill.style.width = percent + '%';
  if (miniCurTime) miniCurTime.textContent = formatTime(audio.currentTime);
  if (miniTotTime) miniTotTime.textContent = formatTime(audio.duration);

  var pageFill = document.getElementById('page-progress-fill');
  var pageCurTime = document.getElementById('page-current-time');
  var pageTotTime = document.getElementById('page-total-time');
  if (pageFill) pageFill.style.width = percent + '%';
  if (pageCurTime) pageCurTime.textContent = formatTime(audio.currentTime);
  if (pageTotTime) pageTotTime.textContent = formatTime(audio.duration);
});

audio.addEventListener('ended', function() { nextSong(); });

document.getElementById('mini-progress-wrapper').addEventListener('click', function(e) {
  if (isNaN(audio.duration)) return;
  var rect = this.getBoundingClientRect();
  audio.currentTime = ((e.clientX - rect.left) / rect.width) * audio.duration;
});

document.getElementById('mini-play-btn').addEventListener('click', togglePlay);
document.getElementById('mini-prev-btn').addEventListener('click', prevSong);
document.getElementById('mini-next-btn').addEventListener('click', nextSong);

// ===== FLOATING HEARTS =====
function createFloatingHearts() {
  var container = document.getElementById('floating-hearts');
  var hearts = ['\ud83d\udc96', '', '\ud83d\udc97', '\ud83d\udc93', '\u2764\ufe0f', '\ud83c\udf39', '\u2728', '\ud83c\udfb5', '\ud83c\udfb6'];
  for (var i = 0; i < 12; i++) {
    var heart = document.createElement('div');
    heart.className = 'floating-heart';
    heart.textContent = hearts[Math.floor(Math.random() * hearts.length)];
    heart.style.left = Math.random() * 100 + '%';
    heart.style.animationDuration = (8 + Math.random() * 12) + 's';
    heart.style.animationDelay = (Math.random() * 10) + 's';
    heart.style.fontSize = (14 + Math.random() * 16) + 'px';
    container.appendChild(heart);
  }
}

// Mobile menu
var menuToggle = document.getElementById('menu-toggle');
var mainNav = document.getElementById('main-nav');
if (menuToggle && mainNav) {
  menuToggle.addEventListener('click', function() { mainNav.classList.toggle('active'); });
}

// Keyboard shortcuts
document.addEventListener('keydown', function(e) {
  if (document.getElementById('lightbox-overlay').classList.contains('active')) return;
  if (e.code === 'Space' && e.target === document.body) { e.preventDefault(); togglePlay(); }
  else if (e.code === 'ArrowRight' && e.target === document.body) { nextSong(); }
  else if (e.code === 'ArrowLeft' && e.target === document.body) { prevSong(); }
});

